<script setup lang="ts">
import { CalendarDays, CheckCircle2, CircleAlert, Clock3, RefreshCw } from '@lucide/vue'
import type { LearnPlanSnapshot } from '~/types/learn-v2-journey'
const { plan } = defineProps<{ plan: LearnPlanSnapshot }>()
const emit = defineEmits<{ editPlan: []; acceptPlan: []; connectCalendar: []; resolveConstraint: [alternative: string] }>()
const kindClass = { learning: 'border-primary/50 bg-primary/10', review: 'border-sky-400/50 bg-sky-400/10', retained_check: 'border-emerald-400/50 bg-emerald-400/10', buffer: 'border-amber-400/50 bg-amber-400/10', rest: 'border-border bg-muted/40' }
</script>
<template>
  <section data-testid="learn-v2-study-rhythm"><header class="flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between"><div><p class="font-inter text-xs uppercase tracking-wide text-primary">Study plan</p><h2 class="mt-1 font-dm-sans text-xl font-bold">A rhythm with room to adapt</h2><p class="mt-1 text-sm text-muted-foreground">Budds owns this plan. Calendar events are an optional projection.</p></div><UiButton variant="secondary" size="sm" @click="emit('editPlan')">Edit availability</UiButton></header><div class="mt-5 grid gap-5 lg:grid-cols-[minmax(0,1fr)_19rem]"><div class="rounded-xl border border-border bg-card"><div class="border-b border-border p-5"><div class="flex items-start gap-3"><component :is="plan.feasibility === 'feasible' ? CheckCircle2 : CircleAlert" class="mt-0.5 h-5 w-5" :class="plan.feasibility === 'feasible' ? 'text-emerald-300' : 'text-amber-300'" /><div><h3 class="font-semibold">{{ plan.headline }}</h3><p class="mt-1 text-sm text-muted-foreground">{{ plan.detail }}</p></div></div><div class="mt-4 flex flex-wrap gap-x-5 gap-y-2 font-inter text-xs text-muted-foreground"><span><Clock3 class="mr-1 inline h-3.5 w-3.5" />{{ plan.weeklyLoadLabel }}</span><span><CalendarDays class="mr-1 inline h-3.5 w-3.5" />{{ plan.targetLabel }}</span></div></div><ol class="divide-y divide-border" aria-label="Upcoming plan sessions"><li v-for="session in plan.sessions" :key="session.id" class="flex items-center gap-3 px-5 py-3"><span class="h-2.5 w-2.5 rounded-full border" :class="kindClass[session.kind]" /><span class="min-w-0 flex-1"><span class="block text-sm font-medium">{{ session.title }}</span><span class="block text-xs text-muted-foreground">{{ session.when }} · {{ session.durationMinutes }} min · {{ session.kind.replace('_', ' ') }}</span></span></li></ol></div><aside class="space-y-4"><UiCard class="gap-3 p-4"><h3 class="font-dm-sans text-base font-semibold">Plan controls</h3><UiButton v-if="plan.feasibility === 'feasible'" class="w-full" @click="emit('acceptPlan')">Accept this plan</UiButton><template v-else-if="plan.alternatives?.length"><p class="text-sm text-muted-foreground">Choose the smallest adjustment that works.</p><button v-for="alternative in plan.alternatives" :key="alternative" type="button" class="w-full rounded-lg border border-border px-3 py-2 text-left text-sm hover:border-primary/40 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring" @click="emit('resolveConstraint', alternative)">{{ alternative }}</button></template><p class="text-xs text-muted-foreground"><RefreshCw class="mr-1 inline h-3.5 w-3.5" />Missed sessions reflow future incomplete work. Completed history never changes.</p></UiCard><UiCard class="gap-3 p-4"><h3 class="font-dm-sans text-base font-semibold">Calendar projection</h3><p class="text-sm text-muted-foreground">{{ plan.calendarStatus === 'ready' ? 'Calendar is connected. Review changes in Budds before accepting them.' : 'Your in-app plan works without a connected calendar.' }}</p><UiButton v-if="plan.calendarStatus !== 'ready'" variant="secondary" size="sm" @click="emit('connectCalendar')">Connect calendar</UiButton></UiCard></aside></div></section>
